// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ACCURAL_DEPOSIT} from "../src/ACCURAL_DEPOSIT.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ACCURAL_DEPOSIT c;

    function setUp() public {
        c = new ACCURAL_DEPOSIT();
    }

    function _runTest(uint256 initial, uint256 more) internal {
        initial = bound(initial, 0, 1000000000000000000000000000000);
        more = bound(more, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP + VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= initial + more);
        try c.Deposit{value: initial}() {} catch { return; }
        uint256 bal_before;
        try c.balances(address(this)) returns (uint256 __r) { bal_before = __r; } catch { return; }
        try c.Deposit{value: more}() {} catch { return; }
        uint256 bal_after;
        try c.balances(address(this)) returns (uint256 __r) { bal_after = __r; } catch { return; }
        assertTrue(bal_after == bal_before + more);
    }

    function testFuzz_runTest(uint256 initial, uint256 more) public {
        _runTest(initial, more);
    }

    receive() external payable {}
}
